var assert = require('assert');
var bytes = require('..');

describe('proof', function () {
  it('keeps default of 2 decimal places when decimalPlaces is omitted', function () {
    assert.strictEqual(bytes(1536, {}), '1.5KB');
    assert.strictEqual(bytes(1536, { thousandsSeparator: ',' }), '1.5KB');
    assert.strictEqual(bytes(1536, { fixedDecimals: true }), '1.50KB');
  });
});

