var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('error message includes descriptive prefix', function () {
    try {
      ms('');
      throw new Error('should have thrown');
    } catch (err) {
      assert.ok(err.message.indexOf('val is not a non-empty string or a valid number') === 0,
        'message was: ' + err.message);
      assert.strictEqual(err.message, 'val is not a non-empty string or a valid number. val=""');
    }
  });
});

